html:
{#- 
    PACE Application — Print Format Template (Jinja)
    Refined Header + Standardized Page 2 Styling
-#}

{%- set _site = frappe.utils.get_url() -%}
{%- macro f(v) -%}{%- if v and v != 'None' -%}{{ v }}{%- else -%}&mdash;{%- endif -%}{%- endmacro -%}
{%- macro fd(v) -%}{%- if v -%}{{ frappe.utils.formatdate(v,'dd-MM-yyyy') }}{%- else -%}&mdash;{%- endif -%}{%- endmacro -%}
{%- macro yn_text(v) -%}{{ "Yes" if v else "No" }}{%- endmacro -%}
{%- macro yn(v) -%}{{ "YES" if v else "NO" }}{%- endmacro -%}

{#- Address Correspondence -#}
{%- set _addr_parts = [] -%}
{%- if doc.address_line_1 -%}{%- set _ = _addr_parts.append(doc.address_line_1) -%}{%- endif -%}
{%- if doc.address_line_2 -%}{%- set _ = _addr_parts.append(doc.address_line_2) -%}{%- endif -%}
{%- if doc.city -%}{%- set _ = _addr_parts.append(doc.city) -%}{%- endif -%}
{%- if doc.district -%}{%- set _ = _addr_parts.append(doc.district) -%}{%- endif -%}
{%- if doc.state -%}{%- set _ = _addr_parts.append(doc.state) -%}{%- endif -%}
{%- if doc.country -%}{%- set _ = _addr_parts.append(doc.country) -%}{%- endif -%}
{%- set _addr_str = _addr_parts | join(', ') -%}
{%- if doc.pincode -%}{%- set _addr_str = _addr_str ~ (' - ' if _addr_str else '') ~ doc.pincode -%}{%- endif -%}

{#- Permanent Address -#}
{%- set _p_addr_parts = [] -%}
{%- if doc.p_address_line_1 -%}{%- set _ = _p_addr_parts.append(doc.p_address_line_1) -%}{%- endif -%}
{%- if doc.p_address_line_2 -%}{%- set _ = _p_addr_parts.append(doc.p_address_line_2) -%}{%- endif -%}
{%- if doc.p_city -%}{%- set _ = _p_addr_parts.append(doc.p_city) -%}{%- endif -%}
{%- if doc.p_district -%}{%- set _ = _p_addr_parts.append(doc.p_district) -%}{%- endif -%}
{%- if doc.p_state -%}{%- set _ = _p_addr_parts.append(doc.p_state) -%}{%- endif -%}
{%- if doc.p_country -%}{%- set _ = _p_addr_parts.append(doc.p_country) -%}{%- endif -%}
{%- set _p_addr_str = _p_addr_parts | join(', ') -%}
{%- if doc.p_pincode -%}{%- set _p_addr_str = _p_addr_str ~ (' - ' if _p_addr_str else '') ~ doc.p_pincode -%}{%- endif -%}

{#- Logo fetched from institution_logo -#}
{%- set _logo_src = '' -%}
{%- set _logo_path = frappe.db.get_single_value('Institution Settings','logo') -%}
{%- if _logo_path -%}
    {%- set _lb64 = get_file_b64(_logo_path) -%}
    {%- if _lb64 -%}
        {%- set _lext = (_logo_path.split('.')[-1] | lower) -%}
        {%- set _lmime = 'image/jpeg' if _lext in ['jpg','jpeg'] else ('image/png' if _lext == 'png' else 'image/svg+xml') -%}
        {%- set _logo_src = 'data:' ~ _lmime ~ ';base64,' ~ _lb64 -%}
    {%- else -%}{%- set _logo_src = _site ~ _logo_path -%}{%- endif -%}
{%- endif -%}

{#- Photo -#}
{%- set _photo_src = '' -%}
{%- if doc.upload_student_photo -%}
    {%- set _pb64 = get_file_b64(doc.upload_student_photo) -%}
    {%- if _pb64 -%}
        {%- set _pext = (doc.upload_student_photo.split('.')[-1] | lower) -%}
        {%- set _pmime = 'image/jpeg' if _pext in ['jpg','jpeg'] else ('image/png' if _pext == 'png' else 'image/webp') -%}
        {%- set _photo_src = 'data:' ~ _pmime ~ ';base64,' ~ _pb64 -%}
    {%- else -%}{%- set _photo_src = _site ~ doc.upload_student_photo -%}{%- endif -%}
{%- endif -%}

{#- Signature -#}
{%- set _sig_src = '' -%}
{%- if doc.student_signature -%}
    {%- set _sb64 = get_file_b64(doc.student_signature) -%}
    {%- if _sb64 -%}
        {%- set _sext = (doc.student_signature.split('.')[-1] | lower) -%}
        {%- set _smime = 'image/jpeg' if _sext in ['jpg','jpeg'] else ('image/png' if _sext == 'png' else 'image/webp') -%}
        {%- set _sig_src = 'data:' ~ _smime ~ ';base64,' ~ _sb64 -%}
    {%- else -%}{%- set _sig_src = _site ~ doc.student_signature -%}{%- endif -%}
{%- endif -%}

<meta name="viewport" content="width=794, initial-scale=1.0">
<style>
    @page {
        size: A4;
        margin: 10mm;
    }
    body {
        font-family: Arial, sans-serif;
        font-size: 9pt;
        line-height: 1.4;
        color: #333;
        margin: 0;
        padding: 0;
    }
    .pf-container {
        border: 1px solid #7b1a1a;
        padding: 0;
        margin-bottom: 20px;
    }
    .pf-header {
        background-color: #7b1a1a;
        color: #fff;
        padding: 10px;
        display: flex;
        align-items: center;
    }
    .pf-header img {
        height: 60px;
        margin-right: 15px;
    }
    .pf-header h1 {
        margin: 0;
        font-size: 14pt;
        flex-grow: 1;
        text-align: center;
    }
    .pf-section {
        border-bottom: 2px solid #7b1a1a;
        background-color: #f8f8f8;
        padding: 5px 10px;
        font-weight: bold;
        text-transform: uppercase;
        color: #7b1a1a;
        font-size: 10pt;
    }
    .pf-row {
        display: flex;
        border-bottom: 1px solid #eee;
    }
    .pf-col {
        flex: 1;
        padding: 6px 10px;
        display: flex;
        flex-direction: column;
    }
    .pf-col-label {
        font-size: 8pt;
        color: #666;
        margin-bottom: 2px;
    }
    .pf-col-value {
        font-weight: 500;
    }
    .pf-table {
        width: 100%;
        border-collapse: collapse;
    }
    .pf-table th, .pf-table td {
        border: 1px solid #eee;
        padding: 6px 10px;
        text-align: left;
    }
    .pf-table th {
        background-color: #fcfcfc;
        font-size: 8pt;
        color: #666;
    }
    .pf-photo-container {
        width: 120px;
        height: 140px;
        border: 1px solid #ddd;
        margin: 10px;
        display: flex;
        align-items: center;
        justify-content: center;
        overflow: hidden;
    }
    .pf-photo-container img {
        max-width: 100%;
        max-height: 100%;
    }

    /* Page 2 Strict Grid Styles */
    .strict-table {
        width: 100%;
        border-collapse: collapse;
        table-layout: fixed;
    }
    .strict-table td {
        border: 1px solid #eee;
        padding: 8px;
        vertical-align: middle;
    }
    .strict-label {
        background-color: #fafafa;
        font-weight: bold;
        font-size: 8.5pt;
        color: #666;
    }
    .strict-img {
        max-height: 100px;
        max-width: 100%;
        display: block;
        margin: 0 auto;
    }
    .text-justify { text-align: justify; }
    .text-center { text-align: center; }
</style>

<!-- PAGE 1 -->
<div class="pf-container">
    <div class="pf-header">
        {% if _logo_src %}<img src="{{ _logo_src }}" alt="Logo">{% endif %}
        <h1>Pace Application Form / Application No: {{ doc.name }}</h1>
    </div>

    <div style="display: flex;">
        <div style="flex-grow: 1;">
            <div class="pf-section">Basic Details</div>
            <div class="pf-row">
                <div class="pf-col">
                    <div class="pf-col-label">Application No:</div>
                    <div class="pf-col-value">{{ doc.name }}</div>
                </div>
                <div class="pf-col">
                    <div class="pf-col-label">Status</div>
                    <div class="pf-col-value">{{ doc.status }}</div>
                </div>
            </div>
            <div class="pf-row">
                <div class="pf-col">
                    <div class="pf-col-label">Programme</div>
                    <div class="pf-col-value">{{ f(doc.programme) }}</div>
                </div>
                <div class="pf-col">
                    <div class="pf-col-label">Submission Date</div>
                    <div class="pf-col-value">{{ fd(doc.submission_date) }}</div>
                </div>
            </div>
            <div class="pf-row">
                <div class="pf-col">
                    <div class="pf-col-label">Full Name</div>
                    <div class="pf-col-value">{{ f(doc.title) }} {{ doc.first_name }} {{ f(doc.middle_name) }} {{ doc.last_name }}</div>
                </div>
            </div>
        </div>
        <div class="pf-photo-container">
            {% if _photo_src %}<img src="{{ _photo_src }}" alt="Photo">{% else %}PHOTO{% endif %}
        </div>
    </div>

    <div class="pf-row">
        <div class="pf-col">
            <div class="pf-col-label">Gender</div>
            <div class="pf-col-value">{{ f(doc.gender) }}</div>
        </div>
        <div class="pf-col">
            <div class="pf-col-label">Date of Birth</div>
            <div class="pf-col-value">{{ fd(doc.date_of_birth) }}</div>
        </div>
        <div class="pf-col">
            <div class="pf-col-label">Email Address</div>
            <div class="pf-col-value">{{ f(doc.email_address) }}</div>
        </div>
        <div class="pf-col">
            <div class="pf-col-label">Mobile Number</div>
            <div class="pf-col-value">{{ f(doc.mobile_number) }}</div>
        </div>
    </div>

    <div class="pf-row">
        <div class="pf-col">
            <div class="pf-col-label">Nationality</div>
            <div class="pf-col-value">{{ f(doc.nationality) }}</div>
        </div>
        <div class="pf-col">
            <div class="pf-col-label">Category</div>
            <div class="pf-col-value">{{ f(doc.category) }}</div>
        </div>
        <div class="pf-col">
            <div class="pf-col-label">Differently-Abled</div>
            <div class="pf-col-value">{{ f(doc.differently_abled) }}{{ " (" ~ doc.please_specify ~ ")" if doc.please_specify }}</div>
        </div>
        <div class="pf-col">
            <div class="pf-col-label">Source of Info</div>
            <div class="pf-col-value">{{ f(doc.how_did_you_hear_about_us) }}</div>
        </div>
    </div>

    {% if doc.currently_employed == "Yes" %}
    <div class="pf-section">Employment Details</div>
    <div class="pf-row">
        <div class="pf-col">
            <div class="pf-col-label">Currently Employed</div>
            <div class="pf-col-value">{{ doc.currently_employed }}</div>
        </div>
        <div class="pf-col">
            <div class="pf-col-label">Organization Name</div>
            <div class="pf-col-value">{{ f(doc.organization_name) }}</div>
        </div>
        <div class="pf-col">
            <div class="pf-col-label">Designation</div>
            <div class="pf-col-value">{{ f(doc.designation) }}</div>
        </div>
    </div>
    {% endif %}

    <div class="pf-section">Parent's Details</div>
    <div class="pf-row">
        <div class="pf-col">
            <div class="pf-col-label">Father's Name</div>
            <div class="pf-col-value">{{ f(doc.father_title) }} {{ f(doc.father_name) }}</div>
        </div>
        <div class="pf-col">
            <div class="pf-col-label">Mother's Name</div>
            <div class="pf-col-value">{{ f(doc.mother_title) }} {{ f(doc.mother_name) }}</div>
        </div>
    </div>

    <div class="pf-section">Passport Details</div>
    <div class="pf-row">
        <div class="pf-col">
            <div class="pf-col-label">Passport Number</div>
            <div class="pf-col-value">{{ f(doc.passport_number) }}</div>
        </div>
        <div class="pf-col">
            <div class="pf-col-label">Date of Expiry</div>
            <div class="pf-col-value">{{ fd(doc.date_of_expiry) }}</div>
        </div>
    </div>

    <div class="pf-section">Address Details</div>
    <table class="strict-table">
        <tr>
            <td colspan="3" class="strict-label" style="color: #7b1a1a; font-size: 9pt; padding: 8px 10px;">Address for Correspondence</td>
        </tr>
        <tr>
            <td style="width: 20%;">
                <div style="display: flex; justify-content: space-between; align-items: center;">
                    <span class="pf-col-label" style="margin: 0;">Country</span>
                    <span class="pf-col-value">{{ f(doc.country) }}</span>
                </div>
            </td>
            <td style="width: 40%;">
                <div style="display: flex; justify-content: space-between; align-items: center;">
                    <span class="pf-col-label" style="margin: 0;">State</span>
                    <span class="pf-col-value">{{ f(doc.state) }}</span>
                </div>
            </td>
            <td style="width: 40%;">
                <div style="display: flex; justify-content: space-between; align-items: center;">
                    <span class="pf-col-label" style="margin: 0;">District</span>
                    <span class="pf-col-value">{{ f(doc.district) }}</span>
                </div>
            </td>
        </tr>
        <tr>
            <td style="width: 15%;">
                <div style="display: flex; justify-content: space-between; align-items: center;">
                    <span class="pf-col-label" style="margin: 0;">City</span>
                    <span class="pf-col-value">{{ f(doc.city) }}</span>
                </div>
            </td>
            <td style="width: 42.5%; padding: 8px 12px;">
                <div style="display: flex; justify-content: space-between; align-items: flex-start;">
                    <span class="pf-col-label" style="margin: 0; white-space: nowrap; margin-right: 10px;">Address Line 1</span>
                    <span class="pf-col-value" style="text-align: right; word-break: break-word;">{{ f(doc.address_line_1) }}</span>
                </div>
            </td>
            <td style="width: 42.5%; padding: 8px 12px;">
                <div style="display: flex; justify-content: space-between; align-items: flex-start;">
                    <span class="pf-col-label" style="margin: 0; white-space: nowrap; margin-right: 10px;">Address Line 2</span>
                    <span class="pf-col-value" style="text-align: right; word-break: break-word;">{{ f(doc.address_line_2) }}</span>
                </div>
            </td>
        </tr>
        <tr>
            <td style="width: 20%;">
                <div style="display: flex; justify-content: space-between; align-items: center;">
                    <span class="pf-col-label" style="margin: 0;">Pincode</span>
                    <span class="pf-col-value">{{ f(doc.pincode) }}</span>
                </div>
            </td>
            <td colspan="2" style="width: 80%;">
                <div style="display: flex; justify-content: space-between; align-items: center;">
                    <span class="pf-col-label" style="margin: 0;">Is Permanent Address Same As Address For Correspondence?</span>
                    <span class="pf-col-value">{{ yn_text(doc.is_permanent_address_same) }}</span>
                </div>
            </td>
        </tr>

        <tr>
            <td colspan="3" class="strict-label" style="color: #7b1a1a; font-size: 9pt; padding: 8px 10px; border-top: 1px solid #7b1a1a;">Permanent Address</td>
        </tr>
        <tr>
            <td style="width: 20%;">
                <div style="display: flex; justify-content: space-between; align-items: center;">
                    <span class="pf-col-label" style="margin: 0;">Country</span>
                    <span class="pf-col-value">{{ f(doc.p_country) }}</span>
                </div>
            </td>
            <td style="width: 40%;">
                <div style="display: flex; justify-content: space-between; align-items: center;">
                    <span class="pf-col-label" style="margin: 0;">State</span>
                    <span class="pf-col-value">{{ f(doc.p_state) }}</span>
                </div>
            </td>
            <td style="width: 40%;">
                <div style="display: flex; justify-content: space-between; align-items: center;">
                    <span class="pf-col-label" style="margin: 0;">District</span>
                    <span class="pf-col-value">{{ f(doc.p_district) }}</span>
                </div>
            </td>
        </tr>
        <tr>
            <td style="width: 15%;">
                <div style="display: flex; justify-content: space-between; align-items: center;">
                    <span class="pf-col-label" style="margin: 0;">City</span>
                    <span class="pf-col-value">{{ f(doc.p_city) }}</span>
                </div>
            </td>
            <td style="width: 42.5%; padding: 8px 12px;">
                <div style="display: flex; justify-content: space-between; align-items: flex-start;">
                    <span class="pf-col-label" style="margin: 0; white-space: nowrap; margin-right: 10px;">Address Line 1</span>
                    <span class="pf-col-value" style="text-align: right; word-break: break-word;">{{ f(doc.p_address_line_1) }}</span>
                </div>
            </td>
            <td style="width: 42.5%; padding: 8px 12px;">
                <div style="display: flex; justify-content: space-between; align-items: flex-start;">
                    <span class="pf-col-label" style="margin: 0; white-space: nowrap; margin-right: 10px;">Address Line 2</span>
                    <span class="pf-col-value" style="text-align: right; word-break: break-word;">{{ f(doc.p_address_line_2) }}</span>
                </div>
            </td>
        </tr>
        <tr>
            <td style="width: 20%;">
                <div style="display: flex; justify-content: space-between; align-items: center;">
                    <span class="pf-col-label" style="margin: 0;">Pincode</span>
                    <span class="pf-col-value">{{ f(doc.p_pincode) }}</span>
                </div>
            </td>
            <td colspan="2"></td>
        </tr>
    </table>

    <div class="pf-section">Education Details (UG Degree)</div>
    <table class="pf-table">
        <thead>
            <tr>
                <th>Institution</th>
                <th>University</th>
                <th>Programme</th>
                <th>Passing Year</th>
                <th>Result</th>
                <th>Marks/CGPA</th>
            </tr>
        </thead>
        <tbody>
            {% for row in doc.ug_degree %}
            <tr>
                <td>{{ f(row.institution_name) }}</td>
                <td>{{ f(row.university) }}</td>
                <td>{{ f(row.programme_studied) }}</td>
                <td>{{ fd(row.year_of_passing) }}</td>
                <td>{{ f(row.result_status) }}</td>
                <td>{{ f(row.obtained_percentagecgpa) }} {{ "(" ~ row.marking_scheme ~ ")" if row.marking_scheme }}</td>
            </tr>
            {% else %}
            <tr><td colspan="6" style="text-align: center;">No data found</td></tr>
            {% endfor %}
        </tbody>
    </table>
</div>

<div style="page-break-after: always;"></div>

<!-- PAGE 2 -->
<div class="pf-container">
    <div class="pf-section">UPLOAD DOCUMENTS</div>
    <table class="strict-table">
        <tr>
            <td class="strict-label" style="width:18%;">Upload Student Photo:</td>
            <td colspan="2" style="width:32%;">
                {% if _photo_src %}<img src="{{ _photo_src }}" class="strict-img">{% else %}<div class="text-center">--</div>{% endif %}
            </td>
            <td class="strict-label" style="width:18%;">Upload Student Signature:</td>
            <td colspan="2" style="width:32%;">
                {% if _sig_src %}<img src="{{ _sig_src }}" class="strict-img">{% else %}<div class="text-center">--</div>{% endif %}
            </td>
        </tr>
        <tr>
            <td class="strict-label" colspan="2" style="width:34%;">Upload Self-signed, Self-declaration Document:</td>
            <td class="text-center" style="width:16%;">{{ yn(doc.self_declaration) }}</td>
            <td class="strict-label" colspan="2" style="width:34%;">Upload Passport / OCI card:</td>
            <td class="text-center" style="width:16%;">{{ yn(doc.passport_oci) }}</td>
        </tr>
        <tr>
            <td class="strict-label" colspan="2">Upload UG Degree Certificate:</td>
            <td class="text-center">{{ yn(doc.ug_degree_certificate) }}</td>
            <td class="strict-label" colspan="2">Upload Govt. ID (Passport for Foreign Nationals):</td>
            <td class="text-center">{{ yn(doc.govt_id) }}</td>
        </tr>
    </table>

    <div class="pf-section" style="margin-top: 20px;">DECLARATION</div>
    <table class="strict-table">
        <tr>
            <td colspan="4" class="text-justify" style="padding: 15px; font-size: 10.5pt; color: #333;">
                I certify that the information submitted by me in support of this application, is true to the best of knowledge and belief. I understand that in the event of any information being found false or incorrect, my admission is liable to be rejected / cancelled at any stage of the program. I undertake to abide by the disciplinary rules and regulations of the institute.
            </td>
        </tr>
        <tr>
            <td style="width: 20%;" class="text-center strict-label">I AGREE</td>
            <td style="width: 30%;" class="text-center">
                <strong>{{ yn_text(doc.i_agree) }}</strong>
            </td>
            <td style="width: 25%;">
                <span style="font-size: 8pt; color: #666;">Applicant Name:</span><br>
                <strong>{{ f(doc.applicant_name) }}</strong>
            </td>
            <td style="width: 25%;">
                <span style="font-size: 8pt; color: #666;">Date:</span><br>
                <strong>{{ fd(doc.submission_date) }}</strong>
            </td>
        </tr>
        <tr>
            <td colspan="4" style="border-top: none; padding-top: 20px;">
                <p style="font-size: 8pt; color: #999; margin: 0;">
                    Generated on: {{ frappe.utils.format_datetime(frappe.utils.now_datetime(), "dd-MM-yyyy HH:mm:ss") }}
                </p>
            </td>
        </tr>
    </table>
</div>
